import { useCallback, useEffect, useState } from 'react';
import AuthDialog from './components/AuthDialog';
import SiteLayout from './components/SiteLayout';
import {
  AdminDashboard,
  ContactPage,
  CoursesPage,
  FeesPage,
  HomePage,
  RequestPage,
  ServiceDetailsPage,
  ServicesPage,
  StudentDashboard,
  SuccessPage,
} from './pages/PortalPages';
import useAuth from './controllers/useAuth';
import useServices from './controllers/useServices';
import { courses } from './models/services';
import {
  cancelStudentRequest,
  createService,
  createPublicInquiry,
  createStudentRequest,
  deleteRequest,
  saveStudentProfile,
  setRequestStatus,
} from './models/portalRepository';
import { createStaffAccount } from './models/staffRepository';
import { findService as findDefaultService } from './models/services';
import './App.css';

function getPath() {
  return window.location.hash.slice(1).split('?')[0] || '/';
}

function getStaffSection() {
  const query = window.location.hash.split('?')[1] || '';
  return new URLSearchParams(query).get('view') === 'accounts' ? 'staff' : 'requests';
}

function App() {
  const { user, profile, isAdmin, loading, authError, isOnline } = useAuth();
  const { services, error: servicesError } = useServices();
  const [path, setPath] = useState(getPath);
  const [staffSection, setStaffSection] = useState(getStaffSection);
  const [authOpen, setAuthOpen] = useState(false);
  const [authMode, setAuthMode] = useState('login');
  const [pendingPath, setPendingPath] = useState('');
  const [notice, setNotice] = useState(null);
  const requestRoute = path.match(/^\/request\/([^/]+)$/);
  const findService = (id) => services.find((service) => service.id === id) || findDefaultService(id);
  const protectedRequest = requestRoute ? findService(requestRoute[1])?.studentOnly : false;

  useEffect(() => {
    const handleNavigation = () => {
      setPath(getPath());
      setStaffSection(getStaffSection());
    };
    window.addEventListener('hashchange', handleNavigation);
    return () => window.removeEventListener('hashchange', handleNavigation);
  }, []);

  const navigate = useCallback((nextPath) => {
    if (getPath() === nextPath) {
      setPath(nextPath);
      window.scrollTo({ top: 0, behavior: 'smooth' });
      return;
    }
    window.location.hash = nextPath;
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }, []);

  const requireStudent = useCallback((nextPath) => {
    if (!user) {
      setPendingPath(nextPath);
      setAuthMode('login');
      setAuthOpen(true);
      return;
    }
    navigate(nextPath);
  }, [navigate, user]);

  useEffect(() => {
    if (loading) return;
    if ((path === '/student' || protectedRequest) && !user) {
      setPendingPath(path);
      setAuthMode('login');
      setAuthOpen(true);
      navigate('/');
    } else if (path === '/staff' && !isAdmin) {
      navigate(user ? '/student' : '/');
      setNotice({ type: 'error', message: 'Staff access is restricted to authorized university accounts.' });
    }
  }, [isAdmin, loading, navigate, path, protectedRequest, user]);

  const openSignIn = useCallback(() => {
    setPendingPath('');
    setAuthMode('login');
    setAuthOpen(true);
  }, []);

  const handleAuthSuccess = useCallback(async () => {
    setAuthOpen(false);
    if (pendingPath) {
      navigate(pendingPath);
      setPendingPath('');
    } else {
      navigate('/student');
    }
  }, [navigate, pendingPath]);

  const dismissNotice = useCallback(() => setNotice(null), []);
  const handleSignOut = useCallback(async () => {
    const { signOutUser } = await import('./models/authRepository');
    try {
      await signOutUser();
      navigate('/');
      setNotice({ type: 'success', message: 'You have been signed out.' });
    } catch (error) {
      setNotice({ type: 'error', message: error.message || 'You could not be signed out. Please try again.' });
    }
  }, [navigate]);

  const serviceMatch = path.match(/^\/services\/([^/]+)$/);
  const requestMatch = path.match(/^\/request\/([^/]+)$/);
  let page;

  if (path === '/' || path === '') {
    page = <HomePage
      navigate={navigate}
      user={user}
      services={services}
      serviceError={servicesError}
      onStudentAccess={() => requireStudent('/student')}
    />;
  } else if (path === '/services') {
    page = <ServicesPage navigate={navigate} user={user} services={services} serviceError={servicesError} />;
  } else if (path === '/courses') {
    page = <CoursesPage courses={courses} navigate={navigate} />;
  } else if (path === '/fees') {
    page = <FeesPage navigate={navigate} services={services} />;
  } else if (serviceMatch) {
    const service = findService(serviceMatch[1]);
    page = service
      ? service.studentOnly && !user
        ? <SuccessPage
            navigate={navigate}
            title="Sign in to view this service"
            message="This service is available to registered students. Sign in to see details and submit a request."
            primaryLabel="Student sign in"
          onPrimary={() => requireStudent(`/services/${service.id}`)}
          />
        : <ServiceDetailsPage
          service={service}
          navigate={navigate}
          onRequest={() => service.studentOnly
            ? requireStudent(`/request/${service.id}`)
            : navigate(`/request/${service.id}`)}
        />
      : <SuccessPage navigate={navigate} title="Service not found" message="This service may have moved or is no longer available." />;
  } else if (requestMatch) {
    const service = findService(requestMatch[1]);
    page = service
      ? <RequestPage
          service={service}
          user={user}
          profile={profile}
          onStudentSubmit={async (request) => {
            const id = await createStudentRequest(user.uid, request);
            return id;
          }}
          onPublicSubmit={async (inquiry) => {
            const id = await createPublicInquiry(inquiry);
            return id;
          }}
          navigate={navigate}
          onSignIn={openSignIn}
        />
      : <SuccessPage navigate={navigate} title="Service not found" message="Choose a service from the service directory to continue." />;
  } else if (path === '/student') {
    page = <StudentDashboard
      user={user}
      profile={profile}
      profileError={authError}
      onSaveProfile={async (details) => {
        await saveStudentProfile(user, details);
        setNotice({ type: 'success', message: 'Your student profile has been updated.' });
      }}
      onCancelRequest={async (id) => {
        await cancelStudentRequest(id);
        setNotice({ type: 'success', message: 'The request has been cancelled.' });
      }}
      navigate={navigate}
    />;
  } else if (path === '/staff') {
    page = isAdmin
      ? <AdminDashboard
          services={services}
          onCreateService={createService}
          onUpdateStatus={setRequestStatus}
          onDeleteRequest={deleteRequest}
          onCreateStaffAccount={createStaffAccount}
          initialSection={staffSection}
        />
      : <div className="content-wrap" role="status">Checking staff access…</div>;
  } else if (path === '/contact') {
    page = <ContactPage onSubmit={createPublicInquiry} />;
  } else if (path === '/submitted') {
    page = <SuccessPage
      navigate={navigate}
      title="Thank you for getting in touch"
      message="Your enquiry has been sent to the university team. Keep the reference number from the confirmation notice for your records."
      primaryLabel="Browse services"
      primaryPath="/services"
    />;
  } else {
    page = <SuccessPage
      navigate={navigate}
      title="Page not found"
      message="The page you were looking for could not be found."
      primaryLabel="Return to home"
      primaryPath="/"
    />;
  }

  return (
    <SiteLayout
      currentPath={path}
      user={user}
      isAdmin={isAdmin}
      loading={loading}
      isOnline={isOnline}
      onSignIn={openSignIn}
      onStudentAccess={() => requireStudent('/student')}
      notice={notice}
      onDismissNotice={dismissNotice}
      onSignOut={handleSignOut}
      navigate={navigate}
    >
      {page}
      {authOpen && (
        <AuthDialog
          initialMode={authMode}
          onClose={() => {
            setAuthOpen(false);
            setPendingPath('');
          }}
          onSuccess={handleAuthSuccess}
        />
      )}
    </SiteLayout>
  );
}

export default App;
