import { useEffect } from 'react';
import universityLogo from '../logo.png';

function SiteLayout({
  children,
  currentPath,
  user,
  isAdmin,
  loading,
  isOnline,
  onSignIn,
  onStudentAccess,
  onSignOut,
  notice,
  onDismissNotice,
  navigate,
}) {
  useEffect(() => {
    const pageTitles = {
      '/courses': 'Courses',
      '/fees': 'Tuition and fees',
      '/services': 'Student services',
      '/contact': 'Contact',
    };
    document.title = `${pageTitles[currentPath] || 'University portal'} | Limkokwing University`;
  }, [currentPath]);

  const links = [
    { label: 'Home', path: '/' },
    { label: 'Services', path: '/services' },
    { label: 'Courses', path: '/courses' },
    { label: 'Fees', path: '/fees' },
    { label: 'Contact', path: '/contact' },
  ];

  return (
    <>
      <header className="site-header">
        <a className="brand" href="#/" aria-label="Limkokwing University home">
          <img
            className="brand-logo"
            src={universityLogo}
            alt=""
          />
          <span className="brand-copy">
            <strong>STUDENT SERVICES</strong>
            <span>MASERU CAMPUS</span>
          </span>
        </a>
        <nav className="main-nav" aria-label="Main navigation">
          {links.map((link) => (
            <a
              className={currentPath === link.path || (link.path === '/services' && currentPath.startsWith('/services')) ? 'active' : ''}
              href={`#${link.path}`}
              key={link.path}
            >
              {link.label}
            </a>
          ))}
          {isAdmin && <a className={currentPath === '/staff' ? 'active' : ''} href="#/staff">Staff</a>}
        </nav>
        <div className="header-actions">
          {loading ? <span className="header-loading" role="status">Loading account</span> : user ? (
            <>
              <button className="button button-outline header-portal" onClick={onStudentAccess}>
                Student portal
              </button>
              <button className="avatar-button" onClick={onSignOut} aria-label="Sign out">
                <span>{(user.displayName || user.email || 'S').charAt(0).toUpperCase()}</span>
                <span className="sign-out-label">Sign out</span>
              </button>
            </>
          ) : (
            <>
              <button className="button button-text header-login" onClick={onSignIn}>Sign in</button>
              <button className="button button-primary header-portal" onClick={onStudentAccess}>Student portal</button>
            </>
          )}
        </div>
      </header>
      {!isOnline && (
        <div className="connection-notice" role="status" aria-live="polite">
          Connection unavailable. Your student data may not load until you reconnect.
        </div>
      )}
      {notice && (
        <div className={`notice notice-${notice.type}`} role="status" aria-live="polite">
          <span>{notice.message}</span>
          <button onClick={onDismissNotice} aria-label="Dismiss notification">Dismiss</button>
        </div>
      )}
      <main id="main-content" tabIndex="-1">{children}</main>
      <footer className="site-footer">
        <div className="footer-inner">
          <a className="brand footer-brand" href="#/" aria-label="Limkokwing University home">
            <img
              className="brand-logo"
              src={universityLogo}
              alt=""
            />
            <span className="brand-copy">
              <strong>STUDENT SERVICES</strong>
              <span>MASERU CAMPUS</span>
            </span>
          </a>
          <p>Student services, made simpler. Supporting your journey at every step.</p>
          <div className="footer-links">
            <a href="#/services">Services</a>
            <a href="#/courses">Courses</a>
            <a href="#/fees">Fees</a>
            <a href="#/contact">Contact</a>
            <a href="mailto:registry@limkokwing.ac.ls">Email the registry</a>
          </div>
        </div>
        <div className="footer-bottom">
          <span>Limkokwing University of Creative Technology, Lesotho</span>
          <span>© {new Date().getFullYear()} Limkokwing University</span>
        </div>
      </footer>
    </>
  );
}

export default SiteLayout;
